// Unlock a reward if the just-finished scripted match reports a win
ScBtlResult <- function ()
{
	local isWin = CMND_BTL_GET_RESULT();
	if (isWin)
	{
		CMND_SET_GLOBAL_BIT_FLAG(518, 1);
		CMND_SKILL_UNLOCK("para_cp0008", "whd0008");
	}
	else
	{
		CMND_SET_GLOBAL_BIT_FLAG(518, 0);
		CMND_SET_GLOBAL_BIT_FLAG(516, 1);
	}
};
